create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','vendedor','cliente');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,email text not null unique,role user_role not null default 'cliente',seller_id uuid references public.profiles(id),customer_id uuid,active boolean not null default true,created_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null,legal_name text,cnpj text,city text,state text,phone text,email text,seller_id uuid references public.profiles(id),active boolean not null default true,created_at timestamptz not null default now());
alter table public.profiles add constraint profiles_customer_fk foreign key(customer_id) references public.customers(id);
create table public.products(id uuid primary key default gen_random_uuid(),plu text not null unique,ean text,name text not null,brand text,size text,status text not null default 'Disponível',suggested_price numeric(12,2) not null default 0,cost_price numeric(12,2) not null default 0,stock integer not null default 0,image_url text,active boolean not null default true,updated_at timestamptz not null default now());
create sequence public.order_number_seq start 1;
create table public.orders(id uuid primary key default gen_random_uuid(),number bigint not null default nextval('public.order_number_seq'),created_by uuid not null references public.profiles(id),customer_id uuid references public.customers(id),seller_id uuid references public.profiles(id),status text not null default 'novo',total numeric(12,2) not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unit_price numeric(12,2) not null);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name,email,role) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),new.email,coalesce((new.raw_user_meta_data->>'role')::public.user_role,'cliente')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role::text from public.profiles where id=auth.uid() $$;
alter table public.profiles enable row level security;alter table public.customers enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
create policy "profile own or admin" on public.profiles for select using(id=auth.uid() or public.my_role()='admin');
create policy "products authenticated" on public.products for select to authenticated using(active=true or public.my_role()='admin');
create policy "customers scoped" on public.customers for select using(public.my_role()='admin' or seller_id=auth.uid() or id=(select customer_id from public.profiles where id=auth.uid()));
create policy "orders scoped select" on public.orders for select using(public.my_role()='admin' or created_by=auth.uid() or seller_id=auth.uid());
create policy "orders create" on public.orders for insert with check(created_by=auth.uid());
create policy "items scoped select" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (public.my_role()='admin' or o.created_by=auth.uid() or o.seller_id=auth.uid())));
create policy "items create" on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.created_by=auth.uid()));
